 async fetchForm(level){const result=await new GLTFLoader().loadAsync(creatureAsset(level,this.partner||'hufflepuff')),model=result.scene;model.updateMatrixWorld(true);const box=new T.Box3().setFromObject(model),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3()),scale=FORM_HEIGHTS[level]/size.y;model.scale.setScalar(scale);model.position.set(-center.x*scale,-box.min.y*scale,-center.z*scale);const meta=result.parser.json.extras?.maximaLocomotion,attackProfile=[];if(meta){const roles=new Map();if(Number.isInteger(meta.bodyNode))roles.set(meta.bodyNode,'body');if(Number.isInteger(meta.headNode))roles.set(meta.headNode,'head');for(const[id,limb]of Object.entries(meta.limbNodes||{}))if(/fore|wing/i.test(id)&&limb.nodes?.length)roles.set(limb.nodes[0],'limb');model.traverse(b=>{const index=result.parser.associations.get(b)?.nodes;if(b.isBone&&roles.has(index))attackProfile.push({bone:b,role:roles.get(index)});});}return{model,level,attackProfile,framingFactor:Math.min(1,1.45/(meta?.restDimensions?.widthToHeight||1)),partner:this.partner||'hufflepuff',clips:result.animations,referenceSpeed:(result.parser.json.extras?.maximaLocomotion?.playbackReferenceSpeed??result.parser.json.extras?.maximaLocomotion?.referenceSpeed)*(result.parser.json.extras?.maximaLocomotion?.referenceSpeedUnit==='modelHeightsPerSecond'?FORM_HEIGHTS[level]:1),forwardYaw:result.parser.json.extras?.maximaLocomotion?.forwardYaw||0};}
