  canvas.addEventListener('pointerup',e=>{if(!down||e.pointerId!==down.id)return;const gesture=down;down=null;if(gesture.drag||this.home||this.focus||this.battle||this.paused)return;const box=canvas.getBoundingClientRect();this.ray.setFromCamera(new T.Vector2((e.clientX-box.left)/box.width*2-1,-((e.clientY-box.top)/box.height)*2+1),this.camera);const hits=this.ray.intersectObjects(Object.values(this.nodes),true);if(hits.length){let o=hits[0].object;while(o&&!o.userData.placeId)o=o.parent;if(o){this.walkTo(o.userData.placeId);return;}}const point=new T.Vector3();if(this.ray.ray.intersectPlane(this.ground,point))this.nav.go(point.x,point.z);});
