  this.creature.position.set(p.x,this.nav.y||0,p.z);this.desiredTarget.set(pose.target.x,pose.target.y,pose.target.z);this.desiredCamera.set(pose.position.x,pose.position.y,pose.position.z);const retry=this.nav.retryInfo,relocated=retry&&retry!==this.lastCameraRetry;this.lastCameraRetry=retry;if(relocated){this.camera.position.copy(this.desiredCamera);this.target.copy(this.desiredTarget);}const rate=pose.firstPerson?18:7;this.camera.position.lerp(this.desiredCamera,1-Math.exp(-dt*rate));if(!pose.firstPerson&&!this.home){const safe=(this.cameraCast||cameraCast)(pose.head,this.camera.position,this.area||0,.1);this.camera.position.set(safe.x,safe.y,safe.z);}this.target.lerp(this.desiredTarget,1-Math.exp(-dt*rate));this.camera.lookAt(this.target);const fov=Number.isFinite(this.camera.fov)?this.camera.fov:40;this.camera.fov=fov+(pose.fov-fov)*(1-Math.exp(-dt*7));this.lensShift(dt);this.camera.updateProjectionMatrix();
