  const dt=this.juice?.step(frameDt)?0:frameDt;this.time+=dt;if(!this.evolution&&!this.home&&!this.focus&&!this.battle&&!this.paused&&dt>0){const motion=this.movementInput(dt);this.nav.step(dt,motion.input);if(Number.isFinite(motion.heading))this.nav.heading=motion.heading;}
  const stage=this.nav.jumpStage;if(stage==='air')this.fallSpeed=Math.max(0,-(this.nav.vy||0));if(stage==='landing'&&this.lastJumpStage==='air'){this.landingPuff();this.juice?.land((this.fallSpeed||0)/3.5);this.onLand?.(this.fallSpeed||0);}if(stage==='anticipation'&&this.lastJumpStage==='ground')this.juice?.crouch();if(stage==='air'&&this.lastJumpStage==='anticipation')this.juice?.takeoff();this.lastJumpStage=stage;this.cameraUpdate(dt);this.updateOcclusion(dt);this.orb.rotation.y+=dt*.6;this.wild.position.y=Math.sin(this.time*2)*.06;this.reaction=Math.max(0,(this.reaction||0)-dt);this.rival.rotation.z=this.rivalHit>0?Math.sin(this.time*25)*.07:0;this.rivalHit=Math.max(0,(this.rivalHit||0)-dt);this.pulses=this.pulses.filter(p=>{p.age+=dt;p.m.position.addScaledVector(p.v,dt);p.m.material.opacity=(p.alpha??1)*(1-p.age/(p.life||1));if(p.age>(p.life||1)){this.effects.remove(p.m);p.m.geometry.dispose();p.m.material.dispose();return false;}return true;});while(this.pulses.length>(this.effectsBudget??45)){const p=this.pulses.shift();this.effects.remove(p.m);p.m.geometry.dispose();p.m.material.dispose();}
  const shake=this.juice&&!this.evolution?this.juice.offset:null,shaking=shake&&(shake.x||shake.y||shake.z);if(shaking){this.camera.position.x+=shake.x;this.camera.position.y+=shake.y;this.camera.position.z+=shake.z;this.camera.rotateZ(shake.roll);this.camera.updateMatrixWorld();}
